  return {complete:false,deferred:true,reason:'update-in-progress',keys};
 const retired=keys.filter(key=>key.startsWith('math-explorer-')&&key!==CACHE);
 if(!retired.length)return {complete:true,deferred:false,keys};
 const clients=await scopedClients();
 const confirmed=await Promise.all(clients.map(currentClient));
 const known=new Set(clients.filter((_,i)=>confirmed[i]).map(client=>client.id));
 if(clients.some(client=>!known.has(client.id)))
  return {complete:false,deferred:true,reason:'legacy-or-unknown-client',keys};
 const current=await caches.open(CACHE);
 const resources=await Promise.all(FILES.map(file=>current.match(new URL(file,self.registration.scope))));
