// The release-specific cache holds all shipped ESM files. Serving those
// directly avoids starting a failed HTTP fetch for every module when the
// origin is stopped. Each upgraded release installs a fresh complete cache.
// Documents and other resources keep their existing network-first behavior.
const networkFirst=event=>fetch(event.request).then(response=>{
 if(response.ok){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(c=>c.put(event.request,copy)));}return response;
}).catch(()=>caches.open(CACHE).then(c=>c.match(event.request,{ignoreSearch:true})).then(r=>r||new Response('此资源尚未缓存。请重新启动本地数学探索。',{status:503,headers:{'Content-Type':'text/plain; charset=utf-8'}})));
